import React, { useState, useEffect, useRef } from 'react';
import { ThemeProvider, Frame, List, TitleBar, Button as React95Button } from '@react95/core';
import styled from 'styled-components';
import GlobalStyles from './GlobalStyles';

// Boot Screen Component
const BootScreen = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: #1e1e1e;  // Dark background
  color: #ffffff;  // Light text
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: 'OMORI_GAME', monospace;
  font-size: 24px;
  z-index: 999;
  opacity: ${({ isVisible }) => (isVisible ? 1 : 0)};
  transition: opacity 1.5s ease-out;
  pointer-events: ${({ isVisible }) => (isVisible ? 'all' : 'none')};
`;

const backgroundImages = [
  "/images/wallpaper1.png",
  "/images/wallpaper2.png",
  "/images/wallpaper3.png", // Add more images as needed
];

// Content Container Component
const ContentContainer = styled.div`
  background-color: #1e1e1e;  // Dark background
  width: 100vw;
  height: 100vh;
  position: fixed;
  top: 0;
  left: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
`;

// Desktop Component
const Desktop = styled.div`
  background-color: #1e1e1e;  // Dark background
  height: 100vh;
  width: 100vw;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
`;

// Window Border Component
const WindowBorder = styled.div`
  padding: 8px;
  box-sizing: border-box;
  display: flex;
  justify-content: center;
  align-items: center;
  border: 3px solid #606060;  // Adjust as needed
  height: 90vh;
  width: 80vw;
  background-color: #2e2e2e;  // Darker background for windows
`;

// Windowed Environment Component
const WindowedEnvironment = styled.div`
  position: relative;
  background-color: #000000;
  height: 100%;
  width: 100%;
  box-sizing: border-box;
  overflow: hidden;
`;

// Background Layers
const BackgroundContainer = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
  background-color: #000000;
  contain: strict;
`;

const BackgroundImageLayer = styled.div`
  position: absolute;
  top: 0;
  left: -20%;
  width: 140%;
  height: 100%;
  background-image: url(${props => props.$bgImage});
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  opacity: ${({ $isActive }) => ($isActive ? 1 : 0)};
  transition: opacity 2s ease-in-out;
  animation: slowSlide 36s ease-in-out infinite alternate;
  will-change: transform, opacity;
  transform: translate3d(0, 0, 0);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  perspective: 1000px;

  @keyframes slowSlide {
    0% {
      transform: translate3d(-8%, 0, 0);
    }
    100% {
      transform: translate3d(8%, 0, 0);
    }
  }
`;

// Taskbar Component
const Taskbar = styled.div`
  background: #c3c7cb;  // Windows 95 light gray taskbar
  height: 40px;
  width: 100%;
  position: absolute;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: center;
  padding: 0 6px;
  box-sizing: border-box;
  border-top: 2px solid #ffffff;
  box-shadow: inset 0 1px 0 #dfdfdf;
  z-index: 100;
`;

// Styled React95 Button Component
const StyledReact95Button = styled(React95Button)`
  && {
    margin-right: 6px;
    font-family: 'OMORI_GAME', monospace;
    font-size: 16px;
    height: 30px;
    padding: 2px 10px;
    background-color: #c3c7cb;  // Classic Windows 95 light gray button
    color: #000000;  // Classic dark text
    border: none;
    box-shadow: inset 1px 1px 0px 1px #ffffff,
                inset -1px -1px 0px 1px #868a8e,
                1px 1px 0 0px #000000;
    cursor: pointer;

    ${({ isActive }) =>
        isActive &&
        `
        background-color: #e0e0e0;
        box-shadow: inset 1px 1px 0px 1px #000000,
                    inset -1px -1px 0px 1px #ffffff,
                    inset 2px 2px 0px #868a8e;
        padding-top: 4px;
        padding-left: 11px;
      `}

    &:focus {
      outline: 1px dotted #000000;
      outline-offset: -4px;
    }
  }
`;

// Clock Component
const Clock = styled.div`
  margin-left: auto;
  font-family: 'OMORI_GAME', monospace;
  font-size: 16px;
  color: #000000;  // Windows 95 clock text
  text-align: center;
  padding: 2px 8px;
  background: #c3c7cb;  // Windows 95 light gray clock background
  box-shadow: inset -1px -1px 0 0 #ffffff,
              inset 1px 1px 0 0 #868a8e,
              inset -2px -2px 0 0 #dfdfdf,
              inset 2px 2px 0 0 #000000;
  user-select: none;
`;

// Draggable Frame Component
const DraggableFrame = styled(Frame)`
  cursor: move;
  position: absolute;
  display: ${({ isVisible }) => (isVisible ? 'block' : 'none')};
`;

// Music Player Styled Components
const MusicPlayerContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
  box-sizing: border-box;
  font-family: 'OMORI_GAME', monospace;
  user-select: none;
`;

const LcdScreen = styled.div`
  background-color: #0c140e;
  color: #39ff14;
  border: 2px solid;
  border-color: #808080 #ffffff #ffffff #808080;
  box-shadow: inset 1px 1px 0 #000000;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
`;

const LcdTopRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 14px;
`;

const LcdTrackName = styled.div`
  font-weight: bold;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 210px;
`;

const LcdStatus = styled.div`
  font-size: 11px;
  color: #00ffff;
  font-weight: bold;
`;

const LcdBottomRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: #a0ff90;
`;

const LcdArtist = styled.div`
  font-size: 11px;
  opacity: 0.85;
`;

const LcdTime = styled.div`
  font-size: 13px;
  font-weight: bold;
`;

const ProgressBarWrapper = styled.div`
  height: 20px;
  background-color: #ffffff;
  border: 2px solid;
  border-color: #808080 #ffffff #ffffff #808080;
  box-shadow: inset 1px 1px 0 #000000;
  position: relative;
  cursor: pointer;
  overflow: hidden;
  box-sizing: border-box;
`;

const ProgressBarFill = styled.div`
  height: 100%;
  background: repeating-linear-gradient(
    90deg,
    #000080,
    #000080 8px,
    #0000bb 8px,
    #0000bb 10px
  );
  transition: width 0.1s linear;
`;

const ControlsRow = styled.div`
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  align-items: center;
`;

const PlayerButton = styled.button`
  font-family: 'OMORI_GAME', monospace;
  font-size: 13px;
  height: 28px;
  padding: 2px 8px;
  background-color: #c3c7cb;
  color: #000000;
  border: none;
  box-shadow: inset 1px 1px 0px 1px #ffffff,
              inset -1px -1px 0px 1px #868a8e,
              1px 1px 0 0px #000000;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  ${({ isActive }) =>
    isActive &&
    `
    background-color: #dfdfdf;
    box-shadow: inset 1px 1px 0px 1px #000000,
                inset -1px -1px 0px 1px #ffffff,
                inset 2px 2px 0px #868a8e;
  `}

  &:active {
    box-shadow: inset 1px 1px 0px 1px #000000,
                inset -1px -1px 0px 1px #ffffff,
