const songs = [
  { id: 'lostnfound', title: 'Lost & Found', artist: 'eastercreeper', src: '/sfx/lostnfound.mp3' },
  { id: 'boot', title: 'Boot Melody', artist: 'Windows 95', src: '/sfx/boot.mp3' },
