// Music Player Content Component
const MusicPlayerContent = ({
  songsList,
  currentSongIndex,
  isPlaying,
  currentTime,
  duration,
  volume,
  isMuted,
  isLooping,
  onSelectSong,
  onTogglePlay,
  onStop,
  onPrev,
  onNext,
  onSeek,
  onVolumeChange,
  onToggleMute,
  onToggleLoop,
}) => {
  const currentSong = songsList[currentSongIndex] || songsList[0];
  const progressPercent = duration > 0 ? Math.min(100, Math.max(0, (currentTime / duration) * 100)) : 0;

  const formatTime = (seconds) => {
    if (isNaN(seconds) || seconds < 0) return '00:00';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleProgressBarClick = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const newPercent = Math.max(0, Math.min(1, clickX / rect.width));
    if (duration > 0) {
      onSeek(newPercent * duration);
    }
  };

  return (
    <MusicPlayerContainer>
      {/* LCD Status Screen */}
      <LcdScreen>
        <LcdTopRow>
          <LcdTrackName>
            {currentSong ? `🎵 [0${currentSongIndex + 1}] ${currentSong.title}` : 'No Track'}
          </LcdTrackName>
          <LcdStatus>{isPlaying ? '▶ PLAYING' : '⏸ PAUSED'}</LcdStatus>
        </LcdTopRow>
        <LcdBottomRow>
          <LcdArtist>{currentSong ? currentSong.artist : ''}</LcdArtist>
          <LcdTime>{formatTime(currentTime)} / {formatTime(duration)}</LcdTime>
        </LcdBottomRow>
      </LcdScreen>

      {/* Interactive Progress Bar */}
      <ProgressBarWrapper onClick={handleProgressBarClick} title="Click to seek">
        <ProgressBarFill style={{ width: `${progressPercent}%` }} />
      </ProgressBarWrapper>

      {/* Playback Controls */}
      <ControlsRow>
        <PlayerButton onClick={onPrev} title="Previous Track">⏮ Prev</PlayerButton>
        <PlayerButton onClick={onTogglePlay} title={isPlaying ? 'Pause' : 'Play'}>
          {isPlaying ? '⏸ Pause' : '▶ Play'}
        </PlayerButton>
        <PlayerButton onClick={onStop} title="Stop">⏹ Stop</PlayerButton>
        <PlayerButton onClick={onNext} title="Next Track">⏭ Next</PlayerButton>
        <PlayerButton onClick={onToggleLoop} isActive={isLooping} title="Toggle Loop">
          🔁 {isLooping ? 'Loop: ON' : 'Loop: OFF'}
        </PlayerButton>
      </ControlsRow>

      {/* Volume Controls */}
      <VolumeRow>
        <PlayerButton onClick={onToggleMute} style={{ minWidth: '32px', padding: '2px 4px' }} title={isMuted ? 'Unmute' : 'Mute'}>
          {isMuted || volume === 0 ? '🔇' : '🔊'}
        </PlayerButton>
        <span style={{ fontWeight: 'bold' }}>Vol:</span>
        <VolumeSlider
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={isMuted ? 0 : volume}
          onChange={(e) => onVolumeChange(parseFloat(e.target.value))}
        />
        <span style={{ minWidth: '36px', textAlign: 'right' }}>
          {Math.round((isMuted ? 0 : volume) * 100)}%
        </span>
      </VolumeRow>

      {/* Playlist Selector */}
      <PlaylistHeader>Track List ({songsList.length}):</PlaylistHeader>
      <PlaylistContainer>
        {songsList.map((song, index) => {
          const isSelected = index === currentSongIndex;
          return (
            <PlaylistItem
              key={song.id}
              isSelected={isSelected}
              onClick={() => onSelectSong(index)}
            >
              <span style={{ marginRight: '6px' }}>
                {isSelected && isPlaying ? '🔊' : isSelected ? '▶' : '💿'}
              </span>
              <span style={{ flex: 1, fontWeight: isSelected ? 'bold' : 'normal' }}>
                {index + 1}. {song.title} - {song.artist}
              </span>
            </PlaylistItem>
          );
        })}
      </PlaylistContainer>
    </MusicPlayerContainer>
  );
};

